/**
 * Table-schema rules, mirroring `backend/core/schema_rules.py`.
 *
 * Kept in step with the Python side on purpose: the dashboard renders a live SQL
 * preview, and a preview generated by different rules than the ones the server
 * executes would show the user a statement they never actually run. When you
 * change a rule here, change it there — `backend/tests/core/test_schema_rules.py`
 * pins the server's behaviour.
 */

export const COLUMN_TYPES = [
  'TEXT',
  'INTEGER',
  'REAL',
  'BLOB',
  'NUMERIC',
  'BOOLEAN',
  'DATETIME',
  'DATE',
  'JSON',
] as const

export type ColumnType = (typeof COLUMN_TYPES)[number]

/** Framework-owned names. See RESERVED_TABLES in backend/core/schema_rules.py. */
export const RESERVED_TABLES = [
  'users',
  'sessions',
  'api_keys',
  'migrations',
  'projects',
  'sqlite_sequence',
  'storage_files',
  'password_reset_tokens',
  'oauth_identities',
  'oauth_states',
  'rate_limit_hits',
]

export type ColumnSpec = {
  name: string
  type: ColumnType
  notNull: boolean
  unique: boolean
  defaultValue: string
}

export const IDENT_RE = /^[A-Za-z_][A-Za-z0-9_]*$/
const NUMERIC_LITERAL_RE = /^-?\d+(\.\d+)?([eE][+-]?\d+)?$/

/**
 * Render a default as a SQL literal.
 *
 * Anything that is not a number, a boolean or NULL becomes a quoted string with
 * embedded quotes doubled, so a hostile default is stored as text rather than
 * executed. Mirrors render_default_literal() in Python.
 */
export function renderDefaultLiteral(raw: string): string | null {
  const value = (raw ?? '').trim()
  if (!value) return null
  if (NUMERIC_LITERAL_RE.test(value)) return value
  const upper = value.toUpperCase()
  if (upper === 'NULL') return 'NULL'
  if (upper === 'TRUE' || upper === 'FALSE') return upper
  return `'${value.replace(/'/g, "''")}'`
}

/** Mirrors build_create_table_ddl() in Python. */
export function buildCreateTableDdl(
  table: string,
  columns: ColumnSpec[],
  primaryKey: string | null
): string {
  const defs = columns.map((col) => {
    const parts = [col.name, col.type]
    if (col.notNull) parts.push('NOT NULL')
    if (col.unique) parts.push('UNIQUE')
    const def = renderDefaultLiteral(col.defaultValue)
    if (def !== null) parts.push(`DEFAULT ${def}`)
    return parts.join(' ')
  })
  if (primaryKey) defs.push(`PRIMARY KEY (${primaryKey})`)
  return `CREATE TABLE IF NOT EXISTS ${table} (${defs.join(', ')})`
}

export type SchemaValidation = {
  ok: boolean
  tableError: string | null
  /** Keyed by column index so each row can show its own message. */
  columnErrors: Record<number, string>
}

export function validateSchema(
  table: string,
  columns: ColumnSpec[],
  primaryKey: string | null
): SchemaValidation {
  const tableErrors: string[] = []
  const columnErrors: Record<number, string> = {}

  const name = (table ?? '').trim()
  if (!name) {
    tableErrors.push('Give the table a name.')
  } else if (!IDENT_RE.test(name)) {
    tableErrors.push(
      'Use letters, digits and underscores only, starting with a letter or underscore.'
    )
  } else if (RESERVED_TABLES.includes(name.toLowerCase())) {
    tableErrors.push(`"${name}" is reserved by the platform. Pick another name.`)
  }

  if (columns.length === 0) {
    tableErrors.push('Add at least one column.')
  }
  if (columns.length > 100) {
    tableErrors.push('A table can have at most 100 columns.')
  }

  const seen = new Map<string, number>()
  columns.forEach((col, index) => {
    const colName = (col.name ?? '').trim()
    if (!colName) {
      columnErrors[index] = 'Name this column.'
      return
    }
    if (!IDENT_RE.test(colName)) {
      columnErrors[index] = 'Letters, digits and underscores only.'
      return
    }
    const key = colName.toLowerCase()
    const firstSeen = seen.get(key)
    if (firstSeen !== undefined) {
      columnErrors[index] = `Duplicate of column ${firstSeen + 1}.`
      return
    }
    seen.set(key, index)

    if (!COLUMN_TYPES.includes(col.type)) {
      columnErrors[index] = `Unsupported type "${col.type}".`
      return
    }
    if ((col.defaultValue ?? '').length > 500) {
      columnErrors[index] = 'Default value is too long.'
      return
    }
    if (col.notNull && col.defaultValue.trim().toUpperCase() === 'NULL') {
      columnErrors[index] = 'A NOT NULL column cannot default to NULL.'
    }
  })

  if (primaryKey && !columns.some((c) => c.name.trim() === primaryKey)) {
    tableErrors.push('The selected primary key column was removed.')
  }

  return {
    ok: tableErrors.length === 0 && Object.keys(columnErrors).length === 0,
    tableError: tableErrors.length ? tableErrors.join(' ') : null,
    columnErrors,
  }
}

/** Shape sent to the server. Empty/absent constraint keys are omitted. */
export function toRequestColumns(columns: ColumnSpec[]) {
  return columns.map((col) => {
    const out: Record<string, string | boolean> = { name: col.name.trim(), type: col.type }
    if (col.notNull) out.not_null = true
    if (col.unique) out.unique = true
    const def = renderDefaultLiteral(col.defaultValue)
    if (def !== null) out.default = col.defaultValue.trim()
    return out
  })
}

/** Sensible starting point: id + created_at, matching the old modal. */
export function defaultColumns(): ColumnSpec[] {
  return [
    { name: 'id', type: 'INTEGER', notNull: true, unique: false, defaultValue: '' },
    { name: 'created_at', type: 'DATETIME', notNull: false, unique: false, defaultValue: 'CURRENT_TIMESTAMP' },
  ]
}